Dim subscriptionDbName As String = "AdventureWorksReplica"
Dim publicationDbName As String = "AdventureWorks"
Dim hostname As String = "adventure-works\garrett1"
Dim webSyncUrl As String = "https://" + publisherInstance + "/SalesOrders/replisapi.dll"
' Create a connection to the Subscriber.
Dim conn As ServerConnection = New ServerConnection(subscriberName)
Dim subscription As MergePullSubscription
Dim agent As MergeSynchronizationAgent
Try
' Connect to the Subscriber.
conn.Connect()
' Define the pull subscription.
subscription = New MergePullSubscription()
subscription.ConnectionContext = conn
subscription.DatabaseName = subscriptionDbName
subscription.PublisherName = publisherName
subscription.PublicationDBName = publicationDbName
subscription.PublicationName = publicationName
' If the pull subscription exists, then start the synchronization.
If subscription.LoadProperties() Then
' Get the agent for the subscription.
agent = subscription.SynchronizationAgent
' Check that we have enough metadata to start the agent.
If agent.PublisherSecurityMode = Nothing Then
' Set the required properties that could not be returned
' from the MSsubscription_properties table.
agent.PublisherSecurityMode = SecurityMode.Integrated
agent.Distributor = publisherInstance
agent.DistributorSecurityMode = SecurityMode.Integrated
agent.HostName = hostname
' Set optional Web synchronization properties.
agent.UseWebSynchronization = True
agent.InternetUrl = webSyncUrl
agent.InternetSecurityMode = SecurityMode.Standard
agent.InternetLogin = winLogin
agent.InternetPassword = winPassword
End If
' Enable agent logging to the console.
agent.OutputVerboseLevel = 1
agent.Output = ""
' Synchronously start the Merge Agent for the subscription.
agent.Synchronize()
Else
' Do something here if the pull subscription does not exist.
Throw New ApplicationException(String.Format( _
"A subscription to '{0}' does not exist on {1}", _
publicationName, subscriberName))
End If
Catch ex As Exception
' Implement appropriate error handling here.
Throw New ApplicationException("The subscription could not be " + _
"synchronized. Verify that the subscription has " + _
"been defined correctly.", ex)
Finally
conn.Disconnect()
End Try

Como especificar mapeamentos de tipo de dados para um Editor Oracle (Programação Transact-SQL de replicação)
Embora um conjunto de mapeamentos de tipo de dados padrão seja fornecidos para Editores Oracle, pode ser necessário especificar diferentes mapeamentos para determinada publicação. Você pode especificar programaticamente mapeamentos de tipo de dados personalizados usando procedimentos armazenados de replicação. Você pode também definir os mapeamentos padrão que são usados ao mapear tipos de dados entre o MicrosoftSQL Server e um DBMS (sistema de gerenciamento de banco de dados) não-SQL Server. Para obter mais informações, consulte Mapeamento de tipo de dados para Publicadores Oracle.
Para definir mapeamentos de tipo de dados personalizados ao criar um artigo que pertence a uma publicação Oracle
Se já não houver uma, crie uma publicação Oracle. Para obter mais informações, consulte Como criar uma publicação de um banco de dados Oracle (Programação Transact-SQL de replicação).
No Distribuidor, execute sp_addarticle. Especifique um valor 0 para @ use_default_datatypes. Para obter mais informações, consulte Como definir um artigo (Programação Transact-SQL de replicação).
No Distribuidor, execute sp_helparticlecolumns para exibir o mapeamento existente para uma coluna em um artigo publicado.
No Distribuidor, execute sp_changearticlecolumndatatype. Especifique o nome do Editor Oracle para @publisher, assim como para @publication, @article e @column, para definir a coluna publicada. Especifique o nome do tipo de dados do SQL Server a mapear para @type, assim como para @length, @precision e @scale, onde aplicável.
No Distribuidor, execute sp_articleview. Isso cria a exibição usada para gerar o instantâneo da publicação Oracle.
Para especificar um mapeamento como mapeamento padrão para um tipo de dados
(Opcional) No Distribuidor de qualquer banco de dados, execute sp_getdefaultdatatypemapping. Especifique @source_dbms, @source_type, @destination_dbms, @destination_version e quaisquer outros parâmetros necessários para identificar a DBMS de origem. As informações sobre o tipo de dados atualmente mapeados no DBMS de destino são retornadas usando os parâmetros de saída.
(Opcional) Para o Distribuidor em qualquer banco de dados, execute sp_helpdatatypemap. Especifique @source_dbms e quaisquer outros parâmetros necessários para filtrar o conjunto de resultados. Observe o valor de mapping_id para o mapeamento desejado no conjunto de resultados.
(Opcional) No Distribuidor em qualquer banco de dados, execute sp_getdefaultdatatypemapping.
Se você souber o valor desejado de mapping_id obtido na etapa 2, especifique-o para @mapping_id.
Se não souber o @source_dbms, especifique os parâmetros @source_dbms, @source_type, @destination_dbms, @destination_type e quaisquer outros parâmetros necessários para identificar um mapeamento existente.
Para localizar tipos de dados válidos para um determinado tipo de dados Oracle
- No Distribuidor em qualquer banco de dados, execute sp_helpdatatypemap. Especifique um valor de ORACLE para @source_dbms e quaisquer outros parâmetros necessários para filtrar o conjunto de resultados.
Exemplo
Este exemplo altera uma coluna com um tipo de dados Oracle de NUMBER de modo que ele seja mapeado ao tipo de dados numérico(38,38) do SQL Server, em vez do tipo de dados padrão flutuante.
EXEC sp_changearticlecolumndatatype
@publication = 'OraPublication',
@publisher = 'OraPublisher',
@article = 'OraArticle',
@column = 'OraArticleCol',
@type = 'numeric',
@scale = 38,
@precision = 38;
GO
Este exemplo de consulta retorna os mapeamentos padrão e mapeamentos alternativos para o tipo de dados CHAR do Oracle 9.
EXEC sp_helpdatatypemap
@source_dbms = N'ORACLE',
@source_version = 9,
@source_type = N'CHAR';
GO
Este exemplo de consulta retorna os mapeamentos padrão para o tipo de dados NUMBER do Oracle 9 quando ele é especificado sem uma escala ou precisão.
EXEC sp_helpdatatypemap
@source_dbms = N'ORACLE',
@source_version = 9,
@source_type = N'NUMBER',
@defaults_only = 1;
GO

sp_link_publication (Transact-SQL)
Sets the configuration and security information used by synchronization triggers of immediate updating subscriptions when connecting to the Publisher. This stored procedure is executed at the Subscriber on the subscription database.
| Security Note |
|---|
When configuring a Publisher with a remote Distributor, the values supplied for all parameters, including job_login and job_password, are sent to the Distributor as plain text. You should encrypt the connection between the Publisher and its remote Distributor before executing this stored procedure. For more information, see Encrypting Connections to SQL Server. |
Important
Under certain conditions, this stored procedure can fail if the Subscriber is running Microsoft SQL Server 2005 Service Pack 1 or later, and the Publisher is running an earlier version. If the stored procedure fails in this scenario, upgrade the Publisher to SQL Server 2005 Service Pack 1 or later.
Syntax
sp_link_publication [ @publisher = ] 'publisher'
, [ @publisher_db = ] 'publisher_db'
, [ @publication = ] 'publication'
, [ @security_mode = ] security_mode
[ , [ @login = ] 'login' ]
[ , [ @password = ]'password' ]
[ , [ @distributor = ] 'distributor' ]
Arguments
[ @publisher= ] 'publisher'
Is the name of the Publisher to link to. publisher is sysname, with no default.[ @publisher_db= ] 'publisher_db'
Is the name of the Publisher database to link to. publisher_db is sysname, with no default.[ @publication= ] 'publication'
Is the name of the publication to link to. publication is sysname, with no default.[ @security_mode= ] security_mode
Is the security mode used by the Subscriber to connect to a remote Publisher for immediate updating. security_mode is int, and can be one of these values. When possible, use Windows Authentication.Value
Description
0
Uses SQL Server Authentication with the login specified in this stored procedure as login and password.
NoteIn previous versions of SQL Server, this option was used to specify a dynamic remote procedure call (RPC).1
Uses the security context (SQL Server Authentication or Windows Authentication) of the user making the change at the Subscriber.
NoteThis account must also exist at the Publisher with sufficient privileges. When using Windows Authentication, security account delegation must be supported.2
Uses an existing, user-defined linked server login created using sp_link_publication.
[ @login= ] 'login'
Is the login. login is sysname, with a default of NULL. This parameter must be specified when security_mode is 0.[ @password= ] 'password'
Is the password. password is sysname, with a default of NULL. This parameter must be specified when security_mode is 0.[ @distributor= ] 'distributor'
Is the name of the Distributor. distributor is sysname, with a default of NULL.
Return Code Values
0 (success) or 1 (failure)
Remarks
sp_link_publication is used by immediate updating subscriptions in transactional replication.
sp_link_publication can be used for both push and pull subscriptions. It can be called before or after the subscription is created. An entry is inserted or updated in the MSsubscription_properties (Transact-SQL) system table.
For push subscriptions, the entry can be cleaned up by sp_subscription_cleanup (Transact-SQL). For pull subscriptions, the entry can be cleaned up by sp_droppullsubscription (Transact-SQL) or sp_subscription_cleanup (Transact-SQL). You can also call sp_link_publication with a NULL password to clear the entry in the MSsubscription_properties (Transact-SQL) system table for security concerns.
The default mode used by an immediate updating Subscriber when it connects to the Publisher does not allow a connection using Windows Authentication. To connect with a mode of Windows Authentication, a linked server has to be set up to the Publisher, and the immediate updating Subscriber should use this connection when updating the Subscriber. This requires the sp_link_publication to be run with security_mode = 2. When using Windows Authentication, security account delegation must be supported.
Example
-- This script uses sqlcmd scripting variables. They are in the form
-- $(MyVariable). For information about how to use scripting variables
-- on the command line and in SQL Server Management Studio, see the
-- "Executing Replication Scripts" section in the topic
-- "Programming Replication Using System Stored Procedures".
-- Execute this batch at the Subscriber.
DECLARE @publication AS sysname;
DECLARE @publicationDB AS sysname;
DECLARE @publisher AS sysname;
DECLARE @login AS sysname;
DECLARE @password AS nvarchar(512);
SET @publication = N'AdvWorksProductTran';
SET @publicationDB = N'AdventureWorks2008R2';
SET @publisher = $(PubServer);
SET @login = $(Login);
SET @password = $(Password);
-- At the subscription database, create a pull subscription to a transactional
-- publication using immediate updating with queued updating as a failover.
EXEC sp_addpullsubscription
@publisher = @publisher,
@publication = @publication,
@publisher_db = @publicationDB,
@update_mode = N'failover',
@subscription_type = N'pull';
-- Add an agent job to synchronize the pull subscription,
-- which uses Windows Authentication when connecting to the Distributor.
EXEC sp_addpullsubscription_agent
@publisher = @publisher,
@publisher_db = @publicationDB,
@publication = @publication,
@job_login = @login,
@job_password = @password;
-- Add a Windows Authentication-based linked server that enables the
-- Subscriber-side triggers to make updates at the Publisher.
EXEC sp_link_publication
@publisher = @publisher,
@publication = @publication,
@publisher_db = @publicationDB,
@security_mode = 0,
@login = @login,
@password = @password;
GO
USE AdventureWorks2008R2;
GO
-- Execute this batch at the Publisher.
DECLARE @publication AS sysname;
DECLARE @subscriptionDB AS sysname;
DECLARE @subscriber AS sysname;
SET @publication = N'AdvWorksProductTran';
SET @subscriptionDB = N'AdventureWorks2008R2Replica';
SET @subscriber = $(SubServer);
-- At the Publisher, register the subscription, using the defaults.
USE [AdventureWorks2008R2]
EXEC sp_addsubscription
@publication = @publication,
@subscriber = @subscriber,
@destination_db = @subscriptionDB,
@subscription_type = N'pull',
@update_mode = N'failover';
GO
Permissions
Only members of the sysadmin fixed server role can execute sp_link_publication.

OpenSqlFilestream API
The OpenSqlFilestream API obtains a Win32 compatible file handle for a FILESTREAM binary large object (BLOB) that is stored in the file system. The handle can be passed to any of the following Win32 APIs: ReadFile, WriteFile, TransmitFile, SetFilePointer, SetEndOfFile, or FlushFileBuffers. If you pass this handle to any other Win32 API, the error ERROR_ACCESS_DENIED is returned. The handle must be closed by passing it to the Win32 CloseHandle API before the transaction is committed or rolled back. Failing to close the handle will cause server-side resource leaks.
All FILESTREAM data container access must be performed in a SQL Server transaction. Transact-SQL statements can also be executed in the same transaction. This maintains consistency between the SQL data and FILESTREAM BLOB data.
To access the FILESTREAM BLOB by using Win32, Windows Authorization must be enabled.
Important
When the file is opened for write access, the transaction is owned by the FILESTREAM agent. Only Win32 file I/O is allowed until the transaction is released. To release the transaction, the write handle must be closed.
Syntax
HANDLE OpenSqlFilestream (
LPCWSTR FilestreamPath,
SQL_FILESTREAM_DESIRED_ACCESS DesiredAccess,
ULONG OpenOptions,
LPBYTE FilestreamTransactionContext,
SIZE_T FilestreamTransactionContextLength,
PLARGE_INTEGER AllocationSize);
Parameters
FilestreamPath
[in] Is the nvarchar(max) path that is returned by the PathName function. PathName must be called from the context of an account that has SQL Server SELECT or UPDATE permissions on the FILESTREAM table and column.DesiredAccess
[in] Sets the mode used to access FILESTREAM BLOB data. This value is passed to the DeviceIoControl Function.Name
Value
Meaning
SQL_FILESTREAM_READ
0
Data can be read from the file.
SQL_FILESTREAM_WRITE
1
Data can be written to the file.
SQL_FILESTREAM_READWRITE
2
Data can be read and written from the file.
Note
These values are defined in the SQL_FILESTREAM_DESIRED_ACCESS enumeration in sqlncli.h.
OpenOptions
[in] The file attributes and flags. This parameter can also include any combination of the following flags.Flag
Value
Meaning
SQL_FILESTREAM_OPEN_NONE
0x00000000:
The file is being opened or created with no special options.
SQL_FILESTREAM_OPEN_FLAG_ASYNC
0x00000001L
The file is being opened or created for asynchronous I/O.
SQL_FILESTREAM_OPEN_FLAG_NO_BUFFERING
0x00000002L
The system opens the file by using no system caching.
SQL_FILESTREAM_OPEN_FLAG_NO_WRITE_THROUGH
0x00000004L
The system does not write through an intermediate cache. Writes go directly to disk.
SQL_FILESTREAM_OPEN_FLAG_SEQUENTIAL_SCAN
0x00000008L
A file is accessed sequentially from beginning to end. The system can use this as a hint to optimize file caching. If an application moves the file pointer for random access, optimal caching may not occur.
SQL_FILESTREAM_OPEN_FLAG_RANDOM_ACCESS
0x00000010L
A file is accessed randomly. The system can use this as a hint to optimize file caching.
FilestreamTransactionContext
[in] The value that is returned by the GET_FILESTREAM_TRANSACTION_CONTEXT function.FilestreamTransactionContextLength
[in] Number of bytes in the varbinary(max) data that is returned by the GET_FILESTREAM_TRANSACTION_CONTEXT function. The function returns an array of N bytes. N is determined by the function and is a property of the byte array that is returned.AllocationSize
[in] Specifies the initial allocation size of the data file in bytes. It is ignored in read mode. This parameter can be NULL, in which case the default file system behavior is used.
Return Value
If the function succeeds, the return value is an open handle to a specified file. If the function fails, the return value is INVALID_HANDLE_VALUE. For extended error information, call GetLastError().
Examples
The following examples show you how to use the OpenSqlFilestream API to obtain a Win32 handle.
using System.IO;
using System;
using System.Collections.Generic;
using System.Text;
using System.Data;
using System.Data.SqlClient;
using System.Data.SqlTypes;
namespace FILESTREAM
{
class Program
{
static void Main(string[] args)
{
SqlConnection sqlConnection = new SqlConnection(
"Integrated Security=true;server=(local)");
SqlCommand sqlCommand = new SqlCommand();
sqlCommand.Connection = sqlConnection;
try
{
sqlConnection.Open();
//The first task is to retrieve the file path
//of the SQL FILESTREAM BLOB that we want to
//access in the application.
sqlCommand.CommandText =
"SELECT Chart.PathName()"
+ " FROM Archive.dbo.Records"
+ " WHERE SerialNumber = 3";
String filePath = null;
Object pathObj = sqlCommand.ExecuteScalar();
if (DBNull.Value != pathObj)
filePath = (string)pathObj;
else
{
throw new System.Exception(
"Chart.PathName() failed"
+ " to read the path name "
+ " for the Chart column.");
}
//The next task is to obtain a transaction
//context. All FILESTREAM BLOB operations
//occur within a transaction context to
//maintain data consistency.
//All SQL FILESTREAM BLOB access must occur in
//a transaction. MARS-enabled connections
//have specific rules for batch scoped transactions,
//which the Transact-SQL BEGIN TRANSACTION statement
//violates. To avoid this issue, client applications
//should use appropriate API facilities for transaction management,
//management, such as the SqlTransaction class.
SqlTransaction transaction = sqlConnection.BeginTransaction("mainTranaction");
sqlCommand.Transaction = transaction;
sqlCommand.CommandText =
"SELECT GET_FILESTREAM_TRANSACTION_CONTEXT()";
Object obj = sqlCommand.ExecuteScalar();
byte[] txContext = (byte[])obj;
//The next step is to obtain a handle that
//can be passed to the Win32 FILE APIs.
SqlFileStream sqlFileStream = new SqlFileStream(filePath, txContext, FileAccess.ReadWrite);
byte[] buffer = new byte[512];
int numBytes = 0;
//Write the string, "EKG data." to the FILESTREAM BLOB.
//In your application this string would be replaced with
//the binary data that you want to write.
string someData = "EKG data.";
Encoding unicode = Encoding.GetEncoding(0);
sqlFileStream.Write(unicode.GetBytes(someData.ToCharArray()),
0,
someData.Length);
//Read the data from the FILESTREAM
//BLOB.
sqlFileStream.Seek(0L, SeekOrigin.Begin);
numBytes = sqlFileStream.Read(buffer, 0, buffer.Length);
string readData = unicode.GetString(buffer);
if (numBytes != 0)
Console.WriteLine(readData);
//Because reading and writing are finished, FILESTREAM
//must be closed. This closes the c# FileStream class,
//but does not necessarily close the the underlying
//FILESTREAM handle.
sqlFileStream.Close();
//The final step is to commit or roll back the read and write
//operations that were performed on the FILESTREAM BLOB.
sqlCommand.Transaction.Commit();
}
catch (System.Exception ex)
{
Console.WriteLine(ex.ToString());
}
finally
{
sqlConnection.Close();
}
return;
}
}
}
